// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < 1e30);
        vm.deal(address(c), amount);
        GasRecorder r = new GasRecorder();
        c.sendMoney(address(r), amount);
        assertTrue(r.paid() && r.gasAtEntry() >= 10000);
    }
}

contract GasRecorder {
    uint256 public gasAtEntry;
    bool public paid;
    receive() external payable {
        gasAtEntry = gasleft();
        paid = true;
    }
}
